#!/usr/bin/env bash
# Writes Homebrew formulas for a release into the current directory.
# Usage: homebrew-formula.sh VERSION MACOS_SHA256 LINUX_SHA256
set -euo pipefail

version="$1"
macos_sha="$2"
linux_sha="$3"
base="https://github.com/vangheem/activity-watch-manager/releases/download/v${version}"
macos_url="${base}/activity-watch-manager-macos-universal.tar.gz"
linux_url="${base}/activity-watch-manager-linux-x86_64.tar.gz"

write_formula() {
  local class="$1"
  local name="$2"
  local desc="$3"
  local caveats="$4"
  cat > "${name}.rb" <<EOF
# Generated by vangheem/activity-watch-manager's release workflow; edits here are overwritten.
class ${class} < Formula
  desc "${desc}"
  homepage "https://github.com/vangheem/activity-watch-manager"
  version "${version}"
  license "MIT"

  on_macos do
    url "${macos_url}"
    sha256 "${macos_sha}"
  end

  on_linux do
    on_intel do
      url "${linux_url}"
      sha256 "${linux_sha}"
    end
  end

  def install
    bin.install "${name}"
  end

  def caveats
    <<~EOS
${caveats}
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/${name} --version")
  end
end
EOF
}

write_formula "AwmServer" "awm-server" \
  "Central ActivityWatch store and UI" \
  "      Start at login, and restart if it exits:
        awm-server install

      Check that it is running:
        awm-server status"

write_formula "AwmCollector" "awm-collector" \
  "Report local ActivityWatch data to awm-server" \
  "      ActivityWatch must be running locally (port 5600).

      Start at login, and restart if it exits:
        awm-collector install --server http://HOST:8787 --token TOKEN

      On the server Mac, --server and --token can be omitted.
      Check that it is reporting:
        awm-collector status"
